            {
                <div class="table-container">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in securitySettings.Sessions)
                            {
                                var isFirst = session == securitySettings.Sessions[0];
                                <tr>
                                    <td>@session.Device @(isFirst ? "(current)" : "")</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (!isFirst)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-label">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="info-text">No active sessions found.</p>
            }
        </div>
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <h2>Appearance Settings</h2>

        <div class="settings-section">
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(selectedTheme == theme)"
                                   @onchange="() => selectedTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(selectedFontSize == size)"
                                   @onchange="() => selectedFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="selectedLanguage">
                    @foreach (var (code, name) in languages)
                    {
                        <option value="@code">@name</option>
                    }
                </select>
            </div>

            <div class="toggle-label">
                <span>Compact Mode</span>
                <label class="switch">
                    <input type="checkbox" @bind="compactMode" />
                    <span class="slider"></span>
                </label>
            </div>

            <h3>Preview</h3>
            <div class="appearance-preview @(selectedTheme.ToLower()) @(compactMode ? "compact" : "")"
                 style="font-size: @(selectedFontSize switch { "Small" => "12px", "Large" => "18px", _ => "14px" });">
                <div class="preview-header">Sample Header</div>
                <div class="preview-body">
                    <p>This is how your content will look with the selected settings.</p>
                    <button class="preview-btn">Sample Button</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </div>
    };
}
