                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
            </div>
        </div>
    </div>
}

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? toastMessage;
    private string toastType = "success";

    // Profile state
    private UserProfile? savedProfile;
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileBio = "";
    private string profileAvatarUrl = "";

    // Notification state
    private NotificationPrefs? notificationPrefs;
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> mutedChannels = new();
    private readonly List<string> allChannels = new() { "general", "announcements", "random", "support", "engineering" };

    // Security state
    private SecuritySettings? securitySettings;
    private bool changePasswordExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool showRevokeConfirmation;
    private string? sessionToRevoke;

    // Appearance state
    private AppearanceSettings? appearanceSettings;
    private string selectedTheme = "System";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;

    private readonly List<(string Code, string Name)> languages = new()
    {
        ("en", "English"), ("es", "Spanish"), ("fr", "French"),
        ("de", "German"), ("ja", "Japanese"), ("zh", "Chinese")
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    ResetProfileFields();
                    break;
                case "Notifications":
                    notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                    emailNotifications = notificationPrefs.EmailNotifications;
                    pushNotifications = notificationPrefs.PushNotifications;
                    weeklyDigest = notificationPrefs.WeeklyDigest;
                    mutedChannels = new List<string>(notificationPrefs.MutedChannels);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    changePasswordExpanded = false;
                    currentPassword = "";
                    newPassword = "";
                    confirmPassword = "";
                    break;
                case "Appearance":
                    appearanceSettings = await SettingsService.GetAppearanceAsync();
                    selectedTheme = appearanceSettings.Theme;
                    selectedFontSize = appearanceSettings.FontSize;
                    selectedLanguage = appearanceSettings.Language;
                    compactMode = appearanceSettings.CompactMode;
                    break;
            }
        }
        catch (Exception ex)
        {
            ShowToast($"Error loading settings: {ex.Message}", "error");
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ResetProfileFields()
    {
        if (savedProfile is not null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileBio = savedProfile.Bio;
            profileAvatarUrl = savedProfile.AvatarUrl;
        }
    }

    private void ShowToast(string message, string type = "success")
    {
        toastMessage = message;
        toastType = type;
    }

    private void DismissToast() => toastMessage = null;

    private string GetPreviewFontSize() => selectedFontSize switch
    {
        "Small" => "12px",
        "Large" => "18px",
        _ => "14px"
    };

    // Profile actions
    private async Task SaveProfile()
    {
        var updatedProfile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(updatedProfile);
        savedProfile = updatedProfile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.", "info");
    }

    // Notification actions
    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        notificationPrefs = prefs;
        ShowToast("Notification preferences saved!");
    }

    private void ToggleChannelMute(string channel)
    {
        if (mutedChannels.Contains(channel))
            mutedChannels.Remove(channel);
        else
            mutedChannels.Add(channel);
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (newPassword != confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            changePasswordExpanded = false;
            ShowToast("Password updated successfully!");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to update password: {ex.Message}", "error");
        }
    }

    private void RequestRevoke(string sessionId)
    {
        sessionToRevoke = sessionId;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
        showRevokeConfirmation = false;
    }

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.");
        }
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        appearanceSettings = settings;
        ShowToast("Appearance settings saved!");
    }
}
